def find_the_city(n, edges, distance_threshold):
    """Find city with fewest reachable neighbors within threshold using Floyd-Warshall."""
    # Initialize distance matrix
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0

    # Fill direct edges (bidirectional)
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)
        dist[v][u] = min(dist[v][u], w)

    # Floyd-Warshall: try each vertex as intermediate
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Find city with fewest reachable within threshold
    result = 0
    min_reachable = n

    for city in range(n):
        count = sum(1 for j in range(n) 
                    if city != j and dist[city][j] <= distance_threshold)
        if count <= min_reachable:
            min_reachable = count
            result = city

    return result
